1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>FirstRun: Docs that work (literally)</title>
7	<link rel="stylesheet" href="assets/site-nav.css">
8	<meta name="description" content="Two apps for docs. Doc-test runs your quickstart in a clean container and proves the fix. Doc-audit finds pages your code changed underneath.">
9	<meta name="color-scheme" content="light">
10	<script>document.documentElement.className="js"</script>
11	<meta property="og:type" content="website">
12	<meta property="og:title" content="FirstRun: Docs that work (literally).">
13	<meta property="og:description" content="Doc-test proves your quickstart works in a clean container. Doc-audit reads git history and finds stale docs pages.">
14	<meta property="og:image" content="assets/og-card-1200x630.jpg">
15	<meta name="twitter:card" content="summary_large_image">
16	<link rel="icon" href="assets/logo.svg" type="image/svg+xml">
17	<link rel="preconnect" href="https://fonts.googleapis.com">
18	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
19	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500;600&display=swap">
20	<style>
21	:root{
22	--bg:oklch(98.2% .004 255);--panel:oklch(99.7% .0015 255);--sunk:oklch(97.1% .005 255);--hover:oklch(96.2% .007 255);
23	--line:oklch(91.6% .007 255);--ink:oklch(22% .012 255);--mut:oklch(50% .013 255);
24	--test:oklch(55% .19 256);--test-bg:oklch(95.6% .026 256);
25	--audit:oklch(52% .2 295);--audit-bg:oklch(95.8% .03 295);
26	--ok:oklch(52% .14 150);--ok-bg:oklch(96.4% .032 150);
27	--bad:oklch(53% .19 27);
28	--sh:0 1px 2px oklch(30% .02 255/.06);
29	--lift:0 1px 2px oklch(30% .03 256/.05),0 8px 24px -10px oklch(35% .06 256/.16),0 24px 56px -28px oklch(35% .06 256/.18);
30	--lift-h:0 2px 4px oklch(30% .03 256/.06),0 16px 36px -12px oklch(35% .07 256/.22),0 36px 72px -30px oklch(35% .07 256/.24);
31	--ease:cubic-bezier(.16,1,.3,1);--road:oklch(22% .012 255/.08);
32	--mono:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
33	--pad:clamp(64px,9vw,120px)}
34	*{box-sizing:border-box;margin:0}
35	html{background:var(--bg);color:var(--ink);font-family:Geist,-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%;scroll-behavior:smooth}
36	body{background:var(--bg);line-height:1.45;font-size:16px;overflow-x:hidden;-webkit-font-smoothing:antialiased}
37	code,pre,.mono{font-family:var(--mono)}
38	a{color:var(--test);text-decoration:none;text-underline-offset:3px}
39	a:hover{text-decoration:underline}
40	p a,.flow a,.sub a{text-decoration:underline}
41	:focus-visible{outline:2px solid var(--test);outline-offset:2px;border-radius:6px}
42	img{max-width:100%}
43	section{max-width:1080px;margin:0 auto;padding:var(--pad) 24px 0}
44	h1{font-size:clamp(34px,5.2vw,58px);line-height:1.04;letter-spacing:-.04em;font-weight:700}
45	h2{font-size:clamp(26px,3.4vw,36px);line-height:1.1;letter-spacing:-.03em;font-weight:700}
46	.sub{color:var(--mut);font-size:16px;margin-top:8px;max-width:40em}
47	.k{font:600 11px/1 var(--mono);letter-spacing:.06em;text-transform:uppercase;color:var(--mut)}
48	.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--lift)}
49	/* motion: one fade and rise as a block enters, staggered inside a group */
50	html.js .rv{opacity:0;transform:translateY(22px);transition:opacity .9s var(--ease),transform .9s var(--ease)}
51	html.js .rv.in{opacity:1;transform:none}
52	.app,.tool,.pr,.shots figure,.anno figure{transition:transform .6s var(--ease),box-shadow .6s var(--ease),border-color .2s}
53	.app:hover,.tool:hover,.pr:hover,.shots figure:hover{transform:translateY(-4px);box-shadow:var(--lift-h)}
54	.ic{width:20px;height:20px;flex:none;display:inline-block}
55	/* buttons */
56	button,.btn{font:inherit;font-weight:600;font-size:15px;background:var(--test);color:#fff;border:1px solid var(--test);border-radius:10px;padding:0 20px;cursor:pointer;min-height:44px;white-space:nowrap;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px;transition:background .15s}
57	button:hover,.btn:hover{background:oklch(49% .18 256)}
58	.ghost{background:var(--panel);color:var(--ink);border:1px solid var(--line);box-shadow:var(--sh)}
59	.ghost:hover{background:var(--hover)}
60	
61	/* hero */
62	#hero{text-align:center;padding-top:clamp(28px,5vw,64px);position:relative;isolation:isolate}
63	#hero:before{content:"";position:absolute;z-index:-1;left:50%;top:-140px;width:min(1400px,140vw);height:760px;transform:translateX(-50%);pointer-events:none;background:radial-gradient(34% 42% at 28% 34%,oklch(84% .09 256/.42),transparent 72%),radial-gradient(30% 38% at 74% 28%,oklch(84% .1 295/.34),transparent 72%),radial-gradient(28% 34% at 52% 78%,oklch(90% .08 150/.30),transparent 72%)}
64	#hero>*{animation:rise 1s var(--ease) both}#hero>:nth-child(2){animation-delay:.06s}#hero>:nth-child(3){animation-delay:.12s}#hero>:nth-child(4){animation-delay:.18s}#hero>:nth-child(n+5){animation-delay:.24s}
65	@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
66	#hero h1{max-width:15em;margin:0 auto}
67	#hero .sub{margin:12px auto 0;font-size:clamp(16px,1.8vw,19px);max-width:34em}
68	.box{display:flex;gap:8px;align-items:center;margin:28px auto 0;max-width:640px;border-radius:16px;padding:7px 7px 7px 20px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--lift)}
69	.box:focus-within{border-color:var(--test);box-shadow:0 0 0 3px var(--test-bg)}
70	.box input{flex:1;min-width:0;font:inherit;font-size:17px;border:0;background:none;color:var(--ink);padding:10px 0;outline:0}
71	.box input::placeholder{color:oklch(60% .01 255)}
72	.chips{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:12px}
73	.chips .lbl{color:var(--mut);font-size:14px;align-self:center;margin-right:2px}
74	.chips button{background:var(--panel);color:var(--ink);border:1px solid var(--line);font-weight:500;font-size:14px;min-height:34px;padding:0 13px;border-radius:99px}
75	.chips button:hover{background:var(--hover);color:var(--test)}
76	.hint{color:var(--mut);font-size:13.5px;margin-top:8px;min-height:1.45em}
77	.hint.cached{color:var(--ok);font-weight:500}
78	
79	/* app tiles */
80	.apps{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:40px;text-align:left}
81	.app{display:flex;flex-direction:column;gap:14px;padding:20px 22px;text-decoration:none;color:var(--ink);transition:border-color .15s}
82	.app:hover{border-color:var(--c)}
83	.app-t{--c:var(--test);--cb:var(--test-bg)}
84	.app-a{--c:var(--audit);--cb:var(--audit-bg)}
85	.app-h{display:flex;align-items:center;gap:12px}
86	.app-i{width:40px;height:40px;border-radius:11px;background:var(--c);color:#fff;display:grid;place-items:center;flex:none}
87	.app-i .ic{width:22px;height:22px}
88	.app-h div b{display:block;font-size:20px;letter-spacing:-.025em}
89	.app-h div span{display:block;color:var(--mut);font-size:14.5px}
90	.app-h .go{margin-left:auto;color:var(--c);font-weight:600;font-size:14px;white-space:nowrap}
91	.jr{list-style:none;padding:0;display:flex;align-items:center;gap:4px}
92	.jr li{display:flex;flex-direction:column;align-items:center;gap:5px;flex:1;font-size:12.5px;font-weight:600;color:var(--ink);min-width:0}
93	.jr li i{width:38px;height:38px;border-radius:50%;background:var(--cb);color:var(--c);display:grid;place-items:center}
94	.jr li.ar{flex:0 0 auto;color:var(--mut);font-weight:400;font-size:15px;padding-bottom:20px}
95	.nums2{display:flex;gap:10px}
96	.nums2 div{flex:1;border-radius:12px;background:var(--sunk);padding:10px 14px}
97	.nums2 b{display:block;font-size:26px;letter-spacing:-.035em;line-height:1.1}
98	.nums2 span{font-size:13px;color:var(--mut)}
99	.nums2 .g b{color:var(--ok)}.nums2 .bl b{color:var(--test)}.nums2 .v b{color:var(--audit)}
100	
101	/* generated prompt */
102	#out{padding-top:28px}
103	.hit{padding:20px 22px;margin-bottom:16px}
104	.hit[hidden],.fresh[hidden]{display:none}
105	.hit-top{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;color:var(--mut);font-size:14px}
106	.pill{display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:13px;border-radius:99px;padding:3px 11px;background:var(--ok-bg);color:var(--ok)}
107	.pill:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
108	.pill.other{background:var(--test-bg);color:var(--test)}
109	.hit h3{font-size:24px;letter-spacing:-.03em;line-height:1.15;margin-top:10px}
110	.hit p{color:var(--mut);margin-top:6px;max-width:40em}
111	.hit-act{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin-top:16px}
112	.hit-act span{color:var(--mut);font-size:14px}
113	.fresh{font-size:15px;color:var(--mut);font-weight:600;margin:0 0 8px 4px}
114	.panel{overflow:hidden}
115	.tabs{display:flex;gap:2px;padding:6px 8px 0;border-bottom:1px solid var(--line);align-items:flex-end}
116	.tabs [role=tab]{font-size:14px;font-weight:600;color:var(--mut);background:none;border:0;border-radius:8px 8px 0 0;padding:0 14px;min-height:40px}
117	.tabs [role=tab]:hover{color:var(--ink);background:none}
118	.tabs [role=tab][aria-selected=true]{color:var(--test);box-shadow:inset 0 -2px 0 var(--test)}
119	.tabs .sp{flex:1}
120	.tabs .cp{margin:0 2px 6px 0;min-height:34px;font-size:14px;padding:0 14px}
121	.how{padding:12px 20px 0;color:var(--mut);font-size:14px}
122	pre{white-space:pre-wrap;word-break:break-word;font-size:13.5px;line-height:1.6;padding:8px 20px 20px;max-height:400px;overflow:auto;color:var(--ink)}
123	.strip{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}
124	.strip li{display:flex;gap:10px;align-items:center;font-size:14px;line-height:1.3;padding:12px 14px}
125	.strip li .ic{color:var(--test)}
126	.cli{padding:14px 18px;margin-top:10px;font-size:13.5px;line-height:1.8;overflow-x:auto;white-space:pre}
127	.cli .p,.cli .c{color:var(--mut)}.cli .p{user-select:none}
128	
129	/* how it works */
130	.row{margin-top:40px}
131	.row-h{display:flex;align-items:center;gap:10px;margin-bottom:12px}
132	.row-h .app-i{width:30px;height:30px;border-radius:8px}
133	.row-h .app-i .ic{width:17px;height:17px}
134	.row-h b{font-size:17px;letter-spacing:-.02em}
135	.row-h a{margin-left:auto;font-size:14px;font-weight:600}
136	.shots{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
137	.shots figure{overflow:hidden}
138	.shots .im{aspect-ratio:16/9;display:flex;align-items:center;justify-content:center;background:var(--sunk);border-bottom:1px solid var(--line)}
139	.shots img{width:100%;height:100%;object-fit:contain;display:block}
140	figcaption{display:flex;gap:10px;align-items:flex-start;padding:12px 14px;font-size:14px;color:var(--mut);line-height:1.35}
141	figcaption b{color:var(--ink);display:block}
142	.n{flex:none;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font:600 12px/1 var(--mono);color:#fff;background:var(--c,var(--test))}
143	.anno{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(0,1fr);gap:14px;align-items:stretch;--c:var(--audit)}
144	.anno figure{position:relative;overflow:hidden;padding:12px}
145	.anno figure img{display:block;width:100%;height:auto;border-radius:8px}
146	.pin{position:absolute;transform:translate(-50%,-50%);width:26px;height:26px;border-radius:50%;background:var(--audit);color:#fff;display:grid;place-items:center;font:600 13px/1 var(--mono);border:2px solid #fff;box-shadow:var(--sh)}
147	.anno ol{list-style:none;padding:0;display:flex;flex-direction:column;gap:10px}
148	.anno li{display:flex;gap:10px;align-items:flex-start;padding:12px 14px;font-size:14px;color:var(--mut);line-height:1.35;flex:1}
149	.anno li b{display:block;color:var(--ink)}
150	
151	/* film: full bleed, no frame, edges fade into the page */
152	#film{max-width:none;padding:clamp(32px,5vw,72px) 0 0}
153	.reel{position:relative;max-width:1680px;margin:0 auto;aspect-ratio:2/1}
154	.reel video{display:block;width:100%;height:100%;object-fit:cover;background:var(--bg);-webkit-mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 11%,#000 89%,transparent);-webkit-mask-composite:source-in;mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent),linear-gradient(180deg,transparent,#000 11%,#000 89%,transparent);mask-composite:intersect;mix-blend-mode:multiply}
155	.ctl{position:absolute;right:max(20px,8%);bottom:9%;display:flex;gap:8px}
156	.ctl button{min-height:36px;padding:0 16px;font-size:13px;color:var(--ink);background:oklch(99.7% .0015 255/.9);border:1px solid var(--line);box-shadow:var(--lift)}
157	.ctl button:hover{background:var(--panel)}
158	
159	/* watch it work: three YouTube videos behind a click-to-load facade */
160	.vids{display:grid;grid-template-columns:2fr 1fr;grid-template-rows:1fr 1fr;gap:18px;margin-top:40px}
161	.vc{display:flex;flex-direction:column;overflow:hidden;transition:transform .6s var(--ease),box-shadow .6s var(--ease)}
162	.vc:hover{transform:translateY(-4px);box-shadow:var(--lift-h)}
163	.vc.big{grid-row:1/3}
164	.vm{position:relative;aspect-ratio:16/9;background:var(--sunk);border-bottom:1px solid var(--line)}
165	.vm img,.vm iframe{position:absolute;inset:0;width:100%;height:100%;border:0;display:block;object-fit:cover}
166	.vp{position:absolute;inset:0;display:block;color:var(--ink);border-radius:0}
167	.vp:hover{text-decoration:none}
168	.vp:focus-visible{outline-offset:-4px;border-radius:0}
169	.pi{position:absolute;left:50%;top:50%;width:64px;height:64px;margin:-32px 0 0 -32px;border-radius:50%;background:oklch(99.7% .0015 255/.94);color:var(--test);display:grid;place-items:center;box-shadow:var(--lift);transition:transform .5s var(--ease),background .2s,color .2s}
170	.pi svg{width:24px;height:24px;margin-left:4px}
171	.vc.big .pi{width:84px;height:84px;margin:-42px 0 0 -42px}.vc.big .pi svg{width:30px;height:30px}
172	.vp:hover .pi,.vp:focus-visible .pi{transform:scale(1.08);background:var(--test);color:oklch(99.7% .0015 255)}
173	.dur{position:absolute;right:12px;bottom:12px;font:600 12.5px/1 var(--mono);color:oklch(99.7% .0015 255);background:oklch(22% .012 255/.82);border-radius:99px;padding:6px 10px}
174	.vt{flex:1;display:flex;flex-direction:column;gap:4px;padding:14px 18px 16px}
175	.vt h3{font-size:16px;letter-spacing:-.02em;line-height:1.25}
176	.vc.big .vt{padding:20px 24px 22px;gap:6px}
177	.vc.big .vt h3{font-size:clamp(19px,2vw,23px);letter-spacing:-.03em}
178	.vt p{color:var(--mut);font-size:14px;max-width:44em}
179	.vt .k{display:flex;gap:8px;align-items:center}
180	@media(max-width:900px){.vids{grid-template-columns:1fr 1fr;grid-template-rows:none}.vc.big{grid-row:auto;grid-column:1/-1}}
181	@media(max-width:560px){.vids{grid-template-columns:1fr}.vc.big .pi{width:68px;height:68px;margin:-34px 0 0 -34px}}
182	@media(prefers-reduced-motion:reduce){.vc,.pi{transition:none}.vc:hover{transform:none}.vp:hover .pi{transform:none}}
183	
184	/* proof */
185	.figs{display:grid;grid-template-columns:1.35fr .8fr 1.35fr .8fr;margin-top:40px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
186	.fg{padding:26px 24px 28px;min-width:0}
187	.fg+.fg{border-left:1px solid var(--line)}
188	.fg .k{display:flex;align-items:center;gap:7px;margin-bottom:16px}
189	.fg .k .ic{width:15px;height:15px}
190	.fn{display:flex;gap:clamp(18px,2.6vw,32px)}
191	.fn div{min-width:0}
192	.fn b{display:block;font-size:clamp(44px,5.4vw,68px);font-weight:700;letter-spacing:-.05em;line-height:.95;font-variant-numeric:tabular-nums}
193	.fn span{display:block;margin-top:8px;font-size:14px;color:var(--mut);line-height:1.3;max-width:12em}
194	.fn .g{color:var(--ok)}.fn .bl{color:var(--test)}.fn .v{color:var(--audit)}
195	.shelf-h{display:flex;align-items:center;gap:12px;margin-top:clamp(56px,7vw,88px)}
196	.shelf-h h3{display:flex;align-items:center;gap:10px;font-size:22px;letter-spacing:-.025em}
197	.shelf-h h3 .ic{color:var(--test)}
198	.arws{margin-left:auto;display:flex;gap:8px}
199	.arw{width:42px;height:42px;min-height:0;padding:0;border-radius:50%;font-size:22px;line-height:1;color:var(--ink);background:var(--panel);border:1px solid var(--line);box-shadow:var(--lift)}
200	.arw:hover{background:var(--hover)}
201	.arw:disabled{opacity:.35;cursor:default}
202	.shelf{display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-padding:0 24px;padding:20px max(24px,calc(50vw - 50% - 24px)) 36px 24px;margin:0 min(-24px,calc(50% - 50vw)) 0 -24px;scrollbar-width:none;outline:0}
203	.shelf::-webkit-scrollbar{display:none}
204	.pr{flex:0 0 min(400px,82vw);scroll-snap-align:start;display:flex;flex-direction:column;overflow:hidden;min-width:0}
205	.pr .shot{display:block;aspect-ratio:2/1;overflow:hidden;background:var(--sunk);border-bottom:1px solid var(--line)}
206	.pr .shot img{width:100%;height:100%;object-fit:cover;object-position:top left;display:block;transition:transform .8s var(--ease)}
207	.pr:hover .shot img{transform:scale(1.03)}
208	.pr-b{padding:18px 20px 20px;display:flex;flex-direction:column;gap:10px;flex:1}
