/* onorca-style dot/grid texture for the hero (dark theme) */
.hero{position:relative;overflow:hidden}
.hero-grid{position:absolute;inset:0;z-index:0;pointer-events:none;
  background-image:radial-gradient(circle, rgba(120,128,160,.16) 1px, transparent 1px);
  background-size:26px 26px;
  -webkit-mask-image:radial-gradient(60% 55% at 50% 38%, #000 0%, transparent 78%);
  mask-image:radial-gradient(60% 55% at 50% 38%, #000 0%, transparent 78%)}
[data-theme="dark"] .hero-grid{background-image:radial-gradient(circle, rgba(160,168,200,.14) 1px, transparent 1px)}
[data-theme="dark"] .hero{background:radial-gradient(120% 78% at 50% -10%, #14142c 0%, var(--paper) 52%)}

/* ══════════════════════════════════════════════
   MINIMAL TOP NAV (onorca-style)
   ══════════════════════════════════════════════ */
/* Transparent over the hero. No background, no border, no blur until you have
.cap-ico .ico{width:30px;height:30px;stroke-width:1.7}
.cap-ico .ico.cap-fill{fill:currentColor;stroke:none}
[data-theme="dark"] .cap-ico{background:#141d3f}

/* ── Capability illustrations (capx) ──
   shared canvas: fills the tile header, dotted field, blue accents */
.capx{position:relative;width:100%;height:100%;min-height:190px;display:flex;align-items:center;
  justify-content:center;border-radius:16px;overflow:hidden;padding:20px;
  background:var(--paper-2);border:1px solid var(--line);
  background-image:radial-gradient(circle,rgba(47,75,214,.08) 1px,transparent 1px);background-size:22px 22px}
[data-theme="dark"] .capx{background-color:rgba(0,0,0,.22);border-color:rgba(255,255,255,.08);
  background-image:radial-gradient(circle,rgba(120,140,255,.1) 1px,transparent 1px)}

/* shared little chip / tile pieces */
.capx-node{display:flex;flex-direction:column;align-items:center;gap:9px;width:96px;padding:16px 10px;border-radius:14px;
  background:var(--white);border:1px solid var(--line);box-shadow:0 6px 16px -10px rgba(11,11,40,.3)}
   THE TOUR — 3D coverflow deck (Deck.tsx)
   Ten square slides on one perspective stage. Depth and rotation come from CSS
   3D transforms so the slide type stays on the browser's own rasteriser and
   every label in the screenshots survives at an angle.
   ══════════════════════════════════════════════ */
.deck{position:relative;padding:clamp(64px,9vh,104px) 0 clamp(56px,8vh,88px);
  background:
    radial-gradient(80% 52% at 50% 0%, rgba(79,107,255,.11) 0%, transparent 62%),
    var(--paper);
  overflow:hidden}
.deck-head{max-width:var(--maxw);margin:0 auto clamp(30px,4.5vh,48px)}
.deck-head .section-h2{max-width:16ch}
.deck-lead{margin-top:16px;max-width:52ch;font-size:17px;line-height:1.55;color:var(--ink-soft)}

/* stage: one shared perspective, edges faded so cards leave rather than clip */
.deck-stage{--cw:clamp(232px,31vw,432px);
/* hero: a faint ground at the bottom edge, under the wordmark and the CTA row.
   Light mode keeps it near the threshold of visible, because the plate is deep
   navy and the hero is off-white paper. */
.pground-hero{bottom:0}
/* The ramp is weighted rather than linear: nothing at the very top so the plate
   grows out of the paper instead of starting on an edge, a long soft rise
   through the wordmark, then full strength from the halfway mark down, where
   the ground sits under the CTA row and the clip and can carry real colour. */
.pground-hero img{object-position:50% 74%;opacity:.24;
  -webkit-mask-image:linear-gradient(180deg,transparent 0,rgba(0,0,0,.12) 18%,rgba(0,0,0,.45) 34%,#000 52%,#000 100%);
          mask-image:linear-gradient(180deg,transparent 0,rgba(0,0,0,.12) 18%,rgba(0,0,0,.45) 34%,#000 52%,#000 100%)}
[data-theme="dark"] .pground-hero img{opacity:.46}

/* stepper: the staircase reads as Build, Run, Automate, Govern in order, and
   the band is already navy, so the plate can carry real weight here */
.pground-stepper{top:0}
.pground-stepper img{object-position:50% 60%;opacity:.26;
  -webkit-mask-image:linear-gradient(180deg,#000 0,#000 42%,transparent 96%);
          mask-image:linear-gradient(180deg,#000 0,#000 42%,transparent 96%)}
[data-theme="dark"] .pground-stepper img{opacity:.22}

/* footer: the horizon sits behind the giant wordmark, low enough that the
   letterforms stay the loudest thing in the band */
.pground-footer{top:0}
.pground-footer img{object-position:50% 30%;opacity:.2;
  -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 30%,#000 100%);
          mask-image:linear-gradient(180deg,transparent 0,#000 30%,#000 100%)}
.footer{position:relative}
.footer > .wrap,.foot-wordmark-wrap{position:relative;z-index:2}

/* ══════════════════════════════════════════════
   WATCH — the two AccuKnox films (Watch.tsx)
   A dark navy band with a photographic ground, two 16:9 facades side by side.
   ══════════════════════════════════════════════ */
.watch{position:relative;overflow:hidden;background:var(--navy);color:#fff;
  padding:clamp(72px,10vh,124px) 0}
.pground-watch{top:0}
.pground-watch img{object-position:50% 62%;opacity:.24;
  -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 34%,#000 72%,transparent 100%);
          mask-image:linear-gradient(180deg,transparent 0,#000 34%,#000 72%,transparent 100%)}
.watch-inner{position:relative;z-index:2}
.watch-head{max-width:var(--maxw);margin:0 auto clamp(30px,4.5vh,46px)}
.watch-head .section-h2{color:#fff;max-width:18ch}
.watch-lead{margin-top:16px;max-width:52ch;font-size:17px;line-height:1.55;color:rgba(255,255,255,.72)}

.watch-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(24px,3vw,40px)}

