document.getElementById("prs").scrollIntoView();
await S(300);
const out = { cards: tr.children.length, start: c(), prevDisabled: document.getElementById("prP").disabled, ctrlHidden: document.getElementById("ctrl").hidden };
document.getElementById("prN").click(); await S(900);
out.afterNext = c(); out.left1 = Math.round(tr.scrollLeft);
tr.focus(); tr.dispatchEvent(new KeyboardEvent("keydown", { key: "ArrowRight", bubbles: true })); await S(900);
out.afterKey = c();
tr.scrollLeft = tr.scrollWidth; await S(700);
out.atEnd = c(); out.nextDisabled = document.getElementById("prN").disabled;
tr.scrollLeft = 0; await S(500);
out.pageOverflow = document.documentElement.scrollWidth - document.documentElement.clientWidth;
return out;

