// Page-wide checks: overflow, H2 centering and subtitles, link underlines, band colors, live numbers.
await new Promise(r => setTimeout(r, 1500));
const de = document.documentElement;
const h2 = [...document.querySelectorAll("main h2")].map(h => ({ t: h.textContent, align: getComputedStyle(h).textAlign, next: h.nextElementSibling ? h.nextElementSibling.tagName + "." + h.nextElementSibling.className : null }));
const links = [...document.querySelectorAll("main a, footer a")].filter(a => a.offsetParent !== null && !a.classList.contains("btn") && !a.classList.contains("vp") && !a.classList.contains("cover") && !a.classList.contains("board"));
const notUnder = links.filter(a => !getComputedStyle(a).textDecorationLine.includes("underline")).map(a => a.outerHTML.slice(0, 90));
const bands = ["steps", "audit", "receipt"].map(id => getComputedStyle(document.getElementById(id)).backgroundColor);
const wide = [...document.querySelectorAll("body *")].filter(e => { const r = e.getBoundingClientRect(); return r.right > de.clientWidth + 1 && !e.closest(".track") && !e.closest(".cmp-s") && !e.closest(".band") && getComputedStyle(e).position !== "fixed" && !e.closest(".reel") && !e.closest("#hero") }).slice(0, 8).map(e => e.tagName + "." + e.className + " " + Math.round(e.getBoundingClientRect().right));
return {
  overflowX: de.scrollWidth - de.clientWidth, h2, linksChecked: links.length, notUnderlined: notUnder, bands,
  nums: ["n-tested", "n-prs", "n-rep", "n-stale"].map(i => i + "=" + document.getElementById(i).textContent),
  count: document.getElementById("count").textContent, ctrlHidden: document.getElementById("ctrl").hidden, cards: document.getElementById("track").children.length,
  trackText: document.getElementById("track").textContent.slice(0, 80), wide
};

